  'dropoff.consent.photoInstructions': { en: 'Please take one clear photo with both your child and yourself in the shot. Staff will use it for safe pickup verification.', zh: '请拍摄一张清晰的照片，包含您的孩子和您本人。工作人员将用它来核实安全接送。', th: 'กรุณาถ่ายภาพที่ชัดเจนหนึ่งภาพที่มีทั้งลูกของคุณและตัวคุณอยู่ในภาพ พนักงานจะใช้เพื่อยืนยันตัวตนตอนรับกลับ', ru: 'Сделайте одну чёткую фотографию вместе с вашим ребёнком. Персонал использует её для безопасной проверки при заборе.', fr: "Merci de prendre une photo nette avec votre enfant et vous-même. Le personnel l'utilisera pour vérifier la récupération en toute sécurité." },
  'dropoff.consent.foodAuth': { en: 'Staff may order food & drinks for my child', zh: '工作人员可以为我的孩子点餐及饮品', th: 'พนักงานสามารถสั่งอาหารและเครื่องดื่มให้ลูกของฉันได้', ru: 'Персонал может заказывать еду и напитки для моего ребёнка', fr: "Le personnel peut commander de la nourriture et des boissons pour mon enfant" },
