  'book.payment.continuePromptpay': { en: 'Continue with PromptPay', zh: '继续使用 PromptPay', th: 'ดำเนินการต่อด้วยพร้อมเพย์', ru: 'Продолжить с PromptPay', fr: 'Continuer avec PromptPay' },
