  'book.payment.mockNote': { en: 'Mock payment — no real charge is made.', zh: '模拟付款——不会产生实际扣款。', th: 'การชำระเงินจำลอง — ไม่มีการเรียกเก็บเงินจริง', ru: 'Тестовая оплата — реального списания не производится.', fr: 'Paiement fictif — aucun débit réel n’est effectué.' },
  'book.payment.paymentOptions': { en: 'Payment options', zh: '付款方式', th: 'ตัวเลือกการชำระเงิน', ru: 'Способы оплаты', fr: 'Options de paiement' },
  'book.payment.payWithPromptpay': { en: 'Pay with PromptPay', zh: '使用 PromptPay 支付', th: 'ชำระเงินด้วยพร้อมเพย์', ru: 'Оплата через PromptPay', fr: 'Payer avec PromptPay' },
  'book.payment.saveScanInstructions': { en: 'Save the QR, then open your banking app and choose Scan / Upload QR to pay.', zh: '保存二维码，然后打开您的银行应用并选择扫描/上传二维码进行付款。', th: 'บันทึก QR แล้วเปิดแอปธนาคารของคุณและเลือกสแกน/อัปโหลด QR เพื่อชำระเงิน', ru: 'Сохраните QR-код, затем откройте банковское приложение и выберите «Сканировать / Загрузить QR» для оплаты.', fr: "Enregistrez le QR, puis ouvrez votre application bancaire et choisissez Scanner / Importer le QR pour payer." },
