  'childReview.titleMany': { en: 'Are these still your children?', zh: '这些仍是您的孩子吗？', th: 'เหล่านี้ยังเป็นบุตรหลานของคุณใช่ไหม?', ru: 'Это по-прежнему ваши дети?', fr: 'Sont-ce toujours vos enfants ?' },
  'childReview.subtitlePublic': { en: 'Choose a saved child for each place, check their name and age, then confirm.', zh: '请为每个名额选择已保存的孩子，核对姓名和年龄，然后确认。', th: 'เลือกเด็กที่บันทึกไว้สำหรับแต่ละที่ ตรวจสอบชื่อและอายุ แล้วกดยืนยัน', ru: 'Выберите сохранённого ребёнка для каждого места, проверьте имя и возраст, затем подтвердите.', fr: 'Choisissez un enfant enregistré pour chaque place, vérifiez son nom et son âge, puis confirmez.' },
  'childReview.subtitle': { en: 'We saved their details from last time — check each one and confirm.', zh: '我们保存了上次的信息——请逐一核对并确认。', th: 'เราบันทึกข้อมูลจากครั้งก่อนไว้แล้ว โปรดตรวจสอบและยืนยันทีละคน', ru: 'Мы сохранили данные с прошлого раза — проверьте каждого и подтвердите.', fr: 'Nous avons gardé leurs informations de la dernière fois — vérifiez et confirmez chacune.' },
  'childReview.childN': { en: 'Child {{n}}', zh: '孩子 {{n}}', th: 'เด็กคนที่ {{n}}', ru: 'Ребёнок {{n}}', fr: 'Enfant {{n}}' },
